SELECT 
FROM cps_inventory_item
WHERE 1 = 1

  AND factory = #{factory}


  AND storage_room = #{storageRoom}


  AND (item_name LIKE CONCAT('%', #{keyword}, '%') OR item_code LIKE CONCAT('%', #{keyword}, '%'))


  AND stock_qty <= alert_threshold


  AND enabled = #{enabled}

ORDER BY factory ASC, storage_room ASC, item_code ASC

